arguments.cmd:
apply_patch <<'PATCH'
*** Begin Patch
*** Add File: output/assets/styles.css
+:root{
+  --navy-950:#0A1628;
+  --navy-900:#0F213D;
+  --navy-850:#132B4C;
+  --slate-950:#0B1220;
+  --slate-900:#121B2B;
+  --slate-800:#1D2A3F;
+  --slate-700:#2B3B55;
+  --slate-600:#3B4E6E;
+  --slate-500:#5C6E88;
+  --slate-400:#8A9BB0;
+  --slate-300:#B6C2D1;
+  --slate-200:#D7DEE8;
+  --slate-150:#E3E8F0;
+  --slate-100:#EEF2F7;
+  --white:#FFFFFF;
+  --teal-500:#0AA6A6;
+  --teal-600:#078F8F;
+  --gold-500:#C7A44B;
+  --gold-600:#B08D36;
+  --shadow-lg:0 22px 55px rgba(10,22,40,.32);
+  --shadow-md:0 10px 24px rgba(10,22,40,.18);
+  --shadow-sm:0 6px 14px rgba(10,22,40,.12);
+  --radius-xl:22px;
+  --radius-lg:16px;
+  --radius-md:12px;
+  --radius-sm:10px;
+  --radius-xs:8px;
+  --container:1200px;
+  --gutter:24px;
+  --font-sans:Inter, ui-sans-serif, system-ui, -apple-system, Segoe UI, Roboto, Helvetica, Arial, "Apple Color Emoji", "Segoe UI Emoji";
+  --font-serif:ui-serif, Georgia, Cambria, "Times New Roman", Times, serif;
+  --ease:cubic-bezier(.2,.8,.2,1);
+}
+
+*{box-sizing:border-box}
+html{color-scheme:light}
+body{
+  margin:0;
+  font-family:var(--font-sans);
+  line-height:1.55;
+  color:var(--slate-900);
+  background:var(--white);
+  -webkit-font-smoothing:antialiased;
+  text-rendering:optimizeLegibility;
+}
+img{max-width:100%;display:block}
+a{color:inherit;text-decoration:none}
+button,input{font:inherit}
+
+.skip-link{
+  position:absolute;
+  left:-999px;
+  top:8px;
+  background:var(--white);
+  padding:10px 12px;
+  border-radius:10px;
+  border:1px solid var(--slate-200);
+  box-shadow:var(--shadow-sm);
+  z-index:9999;
+}
+.skip-link:focus{left:12px}
+
+.container{max-width:var(--container);margin:0 auto;padding:0 var(--gutter)}
+.section{padding:72px 0}
+.section.compact{padding:48px 0}
+.section.tight{padding:32px 0}
+
+.eyebrow{
+  font-size:12px;
+  letter-spacing:.18em;
+  text-transform:uppercase;
+  color:rgba(255,255,255,.78);
+}
+.page-eyebrow{color:var(--slate-500)}
+
+.h1,.h2,.h3,.h4{margin:0}
+.h1{
+  font-family:var(--font-serif);
+  font-weight:700;
+  letter-spacing:-.02em;
+  font-size:44px;
+  line-height:1.1;
+}
+.h2{
+  font-family:var(--font-serif);
+  font-weight:700;
+  letter-spacing:-.015em;
+  font-size:32px;
+  line-height:1.15;
+}
+.h3{font-weight:650;font-size:20px;line-height:1.25}
+.h4{font-weight:650;font-size:16px;line-height:1.25}
+
+.lead{font-size:18px;color:rgba(255,255,255,.85);max-width:62ch}
+.body{color:var(--slate-600);max-width:70ch}
+.muted{color:var(--slate-500)}
+
+.btn{
+  display:inline-flex;
+  align-items:center;
+  justify-content:center;
+  gap:10px;
+  height:44px;
+  padding:0 16px;
+  border-radius:999px;
+  border:1px solid transparent;
+  cursor:pointer;
+  transition:transform .18s var(--ease), box-shadow .18s var(--ease), background .18s var(--ease), border-color .18s var(--ease);
+  user-select:none;
+  white-space:nowrap;
+}
+.btn:focus{outline:3px solid rgba(10,166,166,.35);outline-offset:2px}
+.btn:hover{transform:translateY(-1px)}
+.btn-primary{background:var(--gold-500);color:var(--navy-950);box-shadow:0 10px 22px rgba(199,164,75,.25)}
+.btn-primary:hover{background:var(--gold-600)}
+.btn-secondary{background:rgba(255,255,255,.08);color:var(--white);border-color:rgba(255,255,255,.18)}
+.btn-secondary:hover{background:rgba(255,255,255,.12)}
+.btn-tertiary{background:transparent;border-color:var(--slate-200);color:var(--slate-900)}
+.btn-tertiary:hover{background:var(--slate-100)}
+
+.tag{
+  display:inline-flex;
+  align-items:center;
+  gap:8px;
+  font-size:12px;
+  letter-spacing:.12em;
+  text-transform:uppercase;
+  color:var(--slate-500);
+}
+.tag::before{content:"";width:8px;height:8px;border-radius:99px;background:var(--teal-500)}
+
+.card{
+  background:var(--white);
+  border:1px solid var(--slate-150);
+  border-radius:var(--radius-lg);
+  box-shadow:0 1px 0 rgba(10,22,40,.02);
+}
+.card.pad{padding:22px}
+.card.hover{transition:transform .18s var(--ease), box-shadow .18s var(--ease), border-color .18s var(--ease)}
+.card.hover:hover{transform:translateY(-3px);box-shadow:var(--shadow-md);border-color:rgba(10,166,166,.35)}
+
+.grid{display:grid;gap:20px}
+.grid.cols-2{grid-template-columns:repeat(2,minmax(0,1fr))}
+.grid.cols-3{grid-template-columns:repeat(3,minmax(0,1fr))}
+.grid.cols-4{grid-template-columns:repeat(4,minmax(0,1fr))}
+
+/* Header + nav */
+.header{
+  position:sticky;
+  top:0;
+  z-index:1000;
+  background:rgba(10,22,40,.72);
+  backdrop-filter:saturate(140%) blur(12px);
+  border-bottom:1px solid rgba(255,255,255,.08);
+}
+.header-inner{
+  height:72px;
+  display:flex;
+  align-items:center;
+  justify-content:space-between;
+  gap:20px;
+}
+.brand{
+  display:flex;
+  align-items:center;
+  gap:10px;
+  min-width:220px;
+}
+.brand-mark{
+  width:34px;height:34px;
+  border-radius:10px;
+  background:linear-gradient(135deg, rgba(199,164,75,.95), rgba(10,166,166,.75));
+  box-shadow:0 14px 26px rgba(10,22,40,.28);
+}
+.brand-name{
+  color:var(--white);
+  font-weight:750;
+  letter-spacing:.02em;
+}
+.brand-sub{color:rgba(255,255,255,.6);font-size:12px}
+
+.nav{display:flex;align-items:center;gap:18px}
+.nav a,.nav button{
+  color:rgba(255,255,255,.88);
+  font-weight:560;
+  padding:10px 10px;
+  border-radius:10px;
+}
+.nav a:hover,.nav button:hover{background:rgba(255,255,255,.08)}
+
+.nav-link{display:inline-flex;align-items:center;gap:8px}
+.chev{width:14px;height:14px;opacity:.8}
+
+.nav-actions{display:flex;align-items:center;gap:10px}
+
+.icon-btn{
+  display:inline-flex;
+  align-items:center;
+  justify-content:center;
+  width:44px;height:44px;
+  border-radius:12px;
+  border:1px solid rgba(255,255,255,.16);
+  background:rgba(255,255,255,.06);
+  color:var(--white);
+  cursor:pointer;
+}
+.icon-btn:hover{background:rgba(255,255,255,.1)}
+.icon{width:18px;height:18px}
+
+/* Mega menu */
+.mega-wrap{position:relative}
+.mega{
+  position:absolute;
+  left:0;
+  top:calc(100% + 12px);
+  width:min(980px, calc(100vw - (var(--gutter) * 2)));
+  background:rgba(255,255,255,.98);
+  border:1px solid rgba(10,22,40,.10);
+  border-radius:18px;
+  box-shadow:var(--shadow-lg);
+  overflow:hidden;
+  transform-origin:top left;
+  opacity:0;
+  transform:translateY(-6px) scale(.985);
+  pointer-events:none;
+  transition:opacity .18s var(--ease), transform .18s var(--ease);
+}
+.mega.open{opacity:1;transform:translateY(0) scale(1);pointer-events:auto}
+.mega-top{
+  background:linear-gradient(135deg, rgba(10,22,40,.98), rgba(15,33,61,.96));
+  padding:18px 18px;
+  display:flex;
+  align-items:center;
+  justify-content:space-between;
+  gap:18px;
+}
+.mega-top strong{color:var(--white)}
+.mega-top span{color:rgba(255,255,255,.72)}
+.mega-body{display:grid;grid-template-columns:1.25fr .9fr;gap:0}
+.mega-col{padding:18px}
+.mega-col + .mega-col{border-left:1px solid var(--slate-150)}
+.mega-title{font-size:12px;letter-spacing:.16em;text-transform:uppercase;color:var(--slate-500);margin:0 0 12px}
+.mega-links{display:grid;gap:10px}
+.mega-link{
+  display:flex;
+  align-items:flex-start;
+  justify-content:space-between;
+  gap:14px;
+  padding:12px 12px;
+  border-radius:14px;
+  border:1px solid transparent;
+}
+.mega-link:hover{background:var(--slate-100);border-color:rgba(10,166,166,.25)}
+.mega-link .name{font-weight:650;color:var(--slate-900)}
+.mega-link .desc{font-size:13px;color:var(--slate-600)}
+.mega-link .arrow{width:16px;height:16px;flex:0 0 auto;color:var(--slate-500);margin-top:2px}
+
+.prop-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:10px}
+.pill{
+  display:flex;
+  align-items:center;
+  justify-content:space-between;
+  gap:10px;
+  padding:12px 12px;
+  border:1px solid var(--slate-150);
+  border-radius:14px;
+  background:var(--white);
+}
+.pill:hover{background:var(--slate-100);border-color:rgba(10,166,166,.25)}
+.pill span{font-weight:620}
+
+/* Mobile nav drawer */
+.drawer-overlay{
+  position:fixed;inset:0;
+  background:rgba(10,22,40,.55);
+  opacity:0;pointer-events:none;
+  transition:opacity .18s var(--ease);
+  z-index:1100;
+}
+.drawer-overlay.open{opacity:1;pointer-events:auto}
+.drawer{
+  position:fixed;
+  right:0;top:0;bottom:0;
+  width:min(420px, 92vw);
+  background:rgba(255,255,255,.98);
+  border-left:1px solid rgba(10,22,40,.12);
+  transform:translateX(16px);
+  opacity:0;
+  pointer-events:none;
+  transition:transform .18s var(--ease), opacity .18s var(--ease);
+  z-index:1200;
+  display:flex;
+  flex-direction:column;
+}
+.drawer.open{transform:translateX(0);opacity:1;pointer-events:auto}
+.drawer-head{padding:18px;border-bottom:1px solid var(--slate-150);display:flex;align-items:center;justify-content:space-between;gap:12px}
+.drawer-title{font-weight:750;color:var(--slate-900)}
+.drawer-body{padding:14px 18px 18px;overflow:auto}
+.drawer-actions{padding:14px 18px;border-top:1px solid var(--slate-150);display:flex;gap:10px}
+
+.accordion{display:grid;gap:10px}
+.acc-item{border:1px solid var(--slate-150);border-radius:16px;overflow:hidden;background:var(--white)}
+.acc-btn{
+  width:100%;
+  display:flex;align-items:center;justify-content:space-between;gap:12px;
+  padding:14px 14px;
+  background:transparent;
+  border:0;
+  cursor:pointer;
+}
+.acc-btn span{font-weight:700;color:var(--slate-900);text-align:left}
+.acc-panel{max-height:0;overflow:hidden;transition:max-height .24s var(--ease)}
+.acc-panel-inner{padding:0 14px 14px;display:grid;gap:10px}
+.acc-link{padding:10px 10px;border-radius:12px;background:var(--slate-100);border:1px solid var(--slate-150)}
+.acc-link:hover{border-color:rgba(10,166,166,.35)}
+
+/* Hero */
+.hero{
+  position:relative;
+  padding:78px 0 64px;
+  background:linear-gradient(180deg, rgba(10,22,40,.94), rgba(10,22,40,.72));
+  color:var(--white);
+  overflow:hidden;
+}
+.hero::before{
+  content:"";
+  position:absolute;
+  inset:0;
+  background:
+    linear-gradient(90deg, rgba(10,22,40,.92) 0%, rgba(10,22,40,.60) 46%, rgba(10,22,40,.88) 100%),
+    url("https://images.unsplash.com/photo-1486406146926-c627a92ad1ab?auto=format&fit=crop&w=2000&q=70");
+  background-size:cover;
+  background-position:center;
+  filter:saturate(110%) contrast(105%);
+}
+.hero .container{position:relative}
+.hero-grid{display:grid;grid-template-columns:1.2fr .8fr;gap:26px;align-items:end}
+.hero-card{
+  background:rgba(255,255,255,.06);
+  border:1px solid rgba(255,255,255,.14);
+  border-radius:var(--radius-xl);
+  padding:22px;
+  box-shadow:0 18px 50px rgba(10,22,40,.35);
+}
+.hero-meta{display:flex;align-items:center;justify-content:space-between;gap:12px;color:rgba(255,255,255,.72);font-size:13px}
+.hero-actions{margin-top:18px;display:flex;flex-wrap:wrap;gap:10px}
+
+.stat-row{display:grid;gap:14px}
+.stat{
+  background:rgba(255,255,255,.06);
+  border:1px solid rgba(255,255,255,.14);
+  border-radius:var(--radius-lg);
+  padding:18px;
+}
+.stat strong{display:block;font-size:22px}
+.stat span{display:block;color:rgba(255,255,255,.75)}
+
+/* Announcement banner */
+.banner{
+  background:linear-gradient(135deg, rgba(10,166,166,.18), rgba(199,164,75,.12));
+  border:1px solid rgba(10,22,40,.08);
+  border-radius:18px;
+  padding:18px 18px;
+  display:flex;
+  align-items:center;
+  justify-content:space-between;
+  gap:16px;
+}
+.banner strong{color:var(--slate-900)}
+
+/* Featured insight cards */
+.insights-list{display:grid;gap:12px}
+.insight{
+  display:flex;
+  align-items:center;
+  justify-content:space-between;
+  gap:12px;
+  padding:16px;
+  border-radius:16px;
+  border:1px solid var(--slate-150);
+  background:var(--white);
+}
+.insight:hover{border-color:rgba(10,166,166,.30);box-shadow:var(--shadow-sm)}
+.insight .title{font-weight:700}
+.insight .kicker{color:var(--slate-500);font-size:13px}
+
+/* What we do tabs */
+.tabs{
+  display:grid;
+  grid-template-columns:320px 1fr;
+  gap:24px;
+  align-items:start;
+}
+.tablist{
+  border:1px solid var(--slate-150);
+  border-radius:18px;
+  overflow:hidden;
+  background:var(--white);
+}
+.tab{
+  width:100%;
+  padding:16px 16px;
+  display:flex;
+  align-items:center;
+  justify-content:space-between;
+  gap:12px;
+  border:0;
+  background:transparent;
+  cursor:pointer;
+  text-align:left;
+  transition:background .18s var(--ease);
+}
+.tab + .tab{border-top:1px solid var(--slate-150)}
+.tab strong{font-size:14px;letter-spacing:.12em;text-transform:uppercase;color:var(--slate-600)}
+.tab span{font-weight:750;color:var(--slate-900);display:block;margin-top:4px}
+.tab[aria-selected="true"]{background:linear-gradient(135deg, rgba(10,166,166,.10), rgba(199,164,75,.08))}
+.tab[aria-selected="true"] strong{color:var(--slate-700)}
+
+.tabpanel{
+  border-radius:22px;
+  border:1px solid var(--slate-150);
+  background:
+    radial-gradient(1200px 400px at 20% 20%, rgba(10,166,166,.13), transparent 60%),
+    radial-gradient(900px 320px at 90% 10%, rgba(199,164,75,.12), transparent 55%),
+    linear-gradient(180deg, rgba(255,255,255,1), rgba(238,242,247,.9));
+  padding:26px;
+  box-shadow:var(--shadow-sm);
+}
+.tabpanel .body{max-width:68ch}
+.tabpanel-actions{margin-top:16px;display:flex;gap:10px;flex-wrap:wrap}
+
+/* Newsletter */
+.newsletter{
+  background:linear-gradient(135deg, rgba(10,22,40,.96), rgba(15,33,61,.92));
+  color:var(--white);
+  border-radius:24px;
+  padding:26px;
+  border:1px solid rgba(255,255,255,.10);
+  box-shadow:var(--shadow-md);
+}
+.newsletter-grid{display:grid;grid-template-columns:1.2fr .8fr;gap:18px;align-items:center}
+.form{
+  display:flex;
+  gap:10px;
+  flex-wrap:wrap;
+  justify-content:flex-end;
+}
+.input{
+  height:44px;
+  min-width:240px;
+  padding:0 14px;
+  border-radius:999px;
+  border:1px solid rgba(255,255,255,.18);
+  background:rgba(255,255,255,.08);
+  color:var(--white);
+}
+.input::placeholder{color:rgba(255,255,255,.60)}
+
+/* Insight cards */
+.thumb{
+  border-radius:16px;
+  overflow:hidden;
+  border:1px solid var(--slate-150);
+  background:var(--slate-100);
+  aspect-ratio:16/10;
+}
+.thumb img{width:100%;height:100%;object-fit:cover}
+.insight-card{display:grid;gap:12px}
+.insight-card .meta{display:flex;align-items:center;justify-content:space-between;gap:10px;color:var(--slate-500);font-size:13px}
+.link{display:inline-flex;align-items:center;gap:8px;color:var(--teal-600);font-weight:650}
+.link:hover{text-decoration:underline}
+
+/* Capability cards */
+.cap-grid .card{height:100%}
+.cap-grid .link{margin-top:10px}
+
+/* Carousel */
+.carousel{
+  position:relative;
+  border:1px solid var(--slate-150);
+  border-radius:22px;
+  overflow:hidden;
+  background:var(--white);
+  box-shadow:var(--shadow-sm);
+}
+.carousel-track{display:flex;transition:transform .35s var(--ease)}
+.slide{min-width:100%;padding:22px}
+.carousel-nav{position:absolute;inset:auto 14px 14px auto;display:flex;gap:10px}
+
+/* Footer */
+.footer{
+  background:linear-gradient(180deg, rgba(10,22,40,.98), rgba(10,22,40,.92));
+  color:rgba(255,255,255,.86);
+}
+.footer-grid{display:grid;grid-template-columns:1.1fr 1fr 1fr;gap:20px}
+.footer a{color:rgba(255,255,255,.78)}
+.footer a:hover{color:var(--white)}
+.footer h4{margin:0 0 12px;color:var(--white);font-size:13px;letter-spacing:.16em;text-transform:uppercase}
+.footer ul{list-style:none;padding:0;margin:0;display:grid;gap:10px}
+.foot-bottom{margin-top:28px;padding-top:18px;border-top:1px solid rgba(255,255,255,.10);display:flex;align-items:center;justify-content:space-between;gap:14px;flex-wrap:wrap;color:rgba(255,255,255,.62);font-size:13px}
+
+/* Page hero (non-home) */
+.page-hero{
+  position:relative;
+  padding:70px 0 56px;
+  background:linear-gradient(180deg, rgba(10,22,40,.96), rgba(10,22,40,.82));
+  color:var(--white);
+  overflow:hidden;
+}
+.page-hero::before{
+  content:"";
+  position:absolute;
+  inset:0;
+  background:
+    linear-gradient(90deg, rgba(10,22,40,.92) 0%, rgba(10,22,40,.58) 52%, rgba(10,22,40,.90) 100%),
+    url("https://images.unsplash.com/photo-1496307653780-42ee777d4833?auto=format&fit=crop&w=2000&q=70");
+  background-size:cover;
+  background-position:center;
+}
+.page-hero .container{position:relative}
+.crumbs{display:flex;align-items:center;gap:10px;color:rgba(255,255,255,.72);font-size:13px;flex-wrap:wrap}
+.crumbs a{color:rgba(255,255,255,.78)}
+.crumbs a:hover{color:var(--white)}
+
+.split{display:grid;grid-template-columns:1.2fr .8fr;gap:24px;align-items:start}
+
+.callout{
+  border-radius:22px;
+  padding:22px;
+  background:linear-gradient(135deg, rgba(10,166,166,.10), rgba(199,164,75,.08));
+  border:1px solid rgba(10,22,40,.08);
+}
+
+.list{display:grid;gap:10px}
+.list-item{display:flex;align-items:flex-start;justify-content:space-between;gap:12px;padding:14px;border:1px solid var(--slate-150);border-radius:16px;background:var(--white)}
+.list-item .title{font-weight:720}
+.list-item .sub{color:var(--slate-600);font-size:13px}
+
+.kpi{
+  display:grid;
+  grid-template-columns:repeat(3,minmax(0,1fr));
+  gap:12px;
+}
+.kpi .card{padding:16px;border-radius:18px;background:rgba(255,255,255,.08);border:1px solid rgba(255,255,255,.12)}
+.kpi strong{color:var(--white);font-size:20px}
+.kpi span{color:rgba(255,255,255,.74);display:block;margin-top:6px;font-size:13px}
+
+/* Responsive */
+@media (max-width: 980px){
+  .hero-grid,.newsletter-grid,.split{grid-template-columns:1fr}
+  .tabs{grid-template-columns:1fr}
+  .tablist{display:flex;overflow:auto}
+  .tab{min-width:220px;border-top:0}
+  .tab + .tab{border-left:1px solid var(--slate-150)}
+  .footer-grid{grid-template-columns:1fr}
+}
+@media (max-width: 860px){
+  .nav{display:none}
+}
+@media (max-width: 640px){
+  :root{--gutter:18px}
+  .section{padding:56px 0}
+  .h1{font-size:36px}
+  .h2{font-size:28px}
+  .hero{padding:64px 0 54px}
+  .header-inner{height:68px}
+  .brand{min-width:auto}
+  .input{min-width:100%}
+  .form{justify-content:stretch}
+}
+
+@media (prefers-reduced-motion: reduce){
+  *{scroll-behavior:auto !important}
